import 'package:flutter/material.dart';
class BiometricBackground extends StatelessWidget { const BiometricBackground({super.key,required this.child,this.variant=0}); final Widget child; final int variant; @override Widget build(BuildContext context)=>Stack(children:[Positioned.fill(child:CustomPaint(painter:_GridPainter(Theme.of(context).colorScheme.primary,variant))),child]); }
class _GridPainter extends CustomPainter { const _GridPainter(this.color,this.variant); final Color color; final int variant; @override void paint(Canvas canvas,Size size){final line=Paint()..color=color.withValues(alpha:.1);for(var x=0.0;x<size.width;x+=32){canvas.drawLine(Offset(x,0),Offset(x,size.height),line);}for(var y=0.0;y<size.height;y+=32){canvas.drawLine(Offset(0,y),Offset(size.width,y),line);}final origin=Offset(size.width*(variant.isEven ? .72 : .28),size.height*.25);canvas.drawCircle(origin,86,Paint()..color=color.withValues(alpha:.1));canvas.drawCircle(origin,48,Paint()..color=color.withValues(alpha:.5)..style=PaintingStyle.stroke..strokeWidth=2);}@override bool shouldRepaint(_GridPainter old)=>old.color!=color||old.variant!=variant; }
